<script>
  import { randomString } from '@splendidlabz/utils/dom'
  import { Resizer } from '../Resizer/index.js'
  import { Tab, Tablist, Tabpanels } from '../Tabs/index.js'

  let {
    elem = $bindable(null),

    class: klass = '',
    frameContentClass = '',
    contentClass = '',
    resize = null,

    // Tablist options
    tablistClass = null,
    tablistTarget = randomString(8),
    selectedTabIndex = 0,
    tablistItems = [],

    // Tabpanels options
    tabpanelsClass = null,

    // Slots
    children,
    background,
  } = $props()

  const hasTabs = $derived(tablistItems.length > 0)
  const items = $derived(
    tablistItems.map(tab => (typeof tab === 'string' ? { text: tab } : tab)),
  )
</script>

<!-- Tabpanels -->
{#snippet tablist()}
  <div class="frame-tabs">
    <Tablist
      class="tablist-tab tablist-top {tablistClass}"
      target={tablistTarget}
    >
      {#each items as tab, index (tab)}
        {@const { text, ...tabRest } = tab}
        <Tab {...tabRest} active={index === selectedTabIndex}>
          {text}
        </Tab>
      {/each}
    </Tablist>
  </div>
{/snippet}

<!-- Tabpanels -->
{#snippet tabpanels()}
  <Tabpanels id={tablistTarget} class="border-0 p-0 {tabpanelsClass}">
    {#if children}{@render children()}{/if}
  </Tabpanels>
{/snippet}

{#snippet dot()}
  <svg class="frame-dot" viewBox="0 0 24 24">
    <circle cx="12" cy="12" r="12" />
  </svg>
{/snippet}

<div bind:this={elem} class="browserframe {klass}">
  <div class="vertical gap-0">
    <div class="frame-header">
      <div class="frame-dots">
        {@render dot()}
        {@render dot()}
        {@render dot()}
      </div>
      {#if hasTabs}
        {@render tablist()}
      {/if}
    </div>
    <div class="frame-content stack {frameContentClass}">
      {#if background}
        <div class="background">
          {@render background()}
        </div>
      {/if}

      <div class="content vertical {contentClass}">
        {#if hasTabs}
          {@render tabpanels()}
        {:else if children}{@render children()}{/if}
      </div>

      {#if resize}
        <Resizer options={{ target: '.browserframe', ...resize }} />
      {/if}
    </div>
  </div>
</div>
